function validate(input) {
  const [{ Activity = [] }] = input;
  const kinds = ['open_session', 'end_session', 'scroll_down', 'send_message'];
  const owner = new Map();
  for (const [user, session, date, type] of Activity) {
    if (user === null || session === null || date === null || type === null) return 'Every column of Activity is required.';
    if (!kinds.includes(type)) return `Unknown activity_type ${type}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `activity_date ${date} is not YYYY-MM-DD.`;
    if (owner.has(session) && owner.get(session) !== user) return `Session ${session} belongs to two users.`;
    owner.set(session, user);
  }
  return null;
}

