function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const kinds = ['open_session', 'end_session', 'scroll_down', 'send_message'];
  // offset 0 is 2019-07-27; positive offsets go back in time, negative ones go past the window's end.
  const day = offset => new Date(Date.UTC(2019, 6, 27 - offset)).toISOString().slice(0, 10);
  const Activity = [];
  if (size === 'small') {
    const offsets = [-1, 0, 0, 6, 7, 29, 29, 30, 32];
    const users = 1 + pick(4);
    const sessions = [];
    for (let s = 1; s <= 1 + pick(5); s++) sessions.push([s, 1 + pick(users)]);
    const rows = pick(9);
    for (let i = 0; i < rows; i++) {
      if (Activity.length && rand() < 0.15) { Activity.push([...Activity[pick(Activity.length)]]); continue; }
      const [session, user] = sessions[pick(sessions.length)];
      Activity.push([user, session, day(offsets[pick(offsets.length)]), kinds[pick(kinds.length)]]);
    }
  } else {
    const sessions = [];
    for (let s = 1; s <= 700; s++) sessions.push([s, 1 + pick(300)]);
    for (let i = 0; i < 2000; i++) {
      const [session, user] = sessions[pick(sessions.length)];
      Activity.push([user, session, day(pick(50) - 10), kinds[pick(kinds.length)]]);
    }
  }
  return [{ Activity }];
}
